 IF current_setting('xflow.remediation.target_project_ref',true) IS DISTINCT FROM 'mjfzoikkoykszxzuebdf' OR current_setting('xflow.remediation.change_ref',true) IS DISTINCT FROM 'REVIEW_SERVER_AUTHORITY_CONTAINMENT_V1' THEN RAISE EXCEPTION 'BATCH_TARGET_MARKER_STOP'; END IF;
 IF current_user <> 'postgres' THEN RAISE EXCEPTION 'EXPECTED_POSTGRES_OWNER_ROLE'; END IF;
 FOREACH target IN ARRAY ARRAY['admin_action_audit_logs','admin_notifications','agent_findings','ai_check_test_results','ai_checks','ai_context_engine_policies','ai_eval_scores','ai_fix_recommendations','ai_model_performance_snapshots','ai_operation_logs','ai_rag_inventory','ai_trace_chunks','ai_trace_tool_calls','ai_traces','ai_usage_ledger','alerts','api_keys','app_connections','app_health_runs','app_health_schedules','app_memberships','architecture_audit_reports','aso_audit_reports','assistant_action_logs','assistant_context_snapshots','audit_events','audit_log','audit_runs','audits','automation_rules','automation_runs','billing_adjustment_events','billing_customer_links','cloudflare_connections','commerce_audit_findings','commerce_entitlements','commerce_lifecycle_traces','commerce_products','commerce_purchase_validations','commerce_reconciliation_logs','commerce_stripe_checkout_sessions','commerce_stripe_invoices','commerce_stripe_payment_intents','commerce_stripe_payouts','commerce_stripe_refunds','commerce_subscriptions','commerce_sync_jobs','commerce_verification_processed_events','commerce_verification_runs','commerce_verification_stages','commerce_workspace_governance','connected_app_links','connection_bootstrap_challenges','connector_exports','control_plane_events','control_plane_managed_tokens','copilot_usage_events','credit_ledger','deploy_governance_checks','deploy_governance_policies','deployment_targets','developer_api_request_logs','developer_api_usage_events','ecosystem_app_audit_summaries','ecosystem_app_memberships','ecosystem_audit_requests','ecosystem_entitlement_snapshots','ecosystem_legal_consent_snapshots','ecosystem_trial_decision_events','ecosystem_trial_decisions','ecosystem_trial_eligibility','ecosystem_trial_events','entitlement_grants','event_dedupes','event_ingest_attempts','events','findings','forum_ai_artifacts','forum_challenge_events','forum_rate_limit_events','forum_search_events','forum_thread_views','forum_xp_events','guard_overrides','guard_rules','guard_runtime_evaluations','guard_validation_findings','guard_validation_runs','idempotency_cache','inbound_replay_guards','ingest_rate_buckets','integration_runtime_state','job_runs','jobs','meter_app_xflow_links','meter_apps','meter_ingest_rejections','meter_model_rates','meter_usage_events','metric_definitions','metric_snapshots','mfa_reset_tokens','operator_readiness_impact_events','orgs','ownership_verifications','payment_monitor_stripe_mappings','project_github_connections','project_scan_files','project_scan_findings','project_scan_reports','project_scan_runs','project_scan_source_payloads','redaction_audit_events','requests_log','responsive_audit_runs','responsive_ignore_rules','sanctions_screening_runs','scan_schedules','scans','security_alert_events','security_audit_exports','security_audit_logs','security_findings','security_integrations','security_notification_preferences','security_scan_artifacts','security_scan_checks','security_scan_schedules','security_scans','sessions','site_audit_schedules','stripe_events','stripe_webhook_processing','stripe_webhook_rate_buckets','subscription_items','superadmin_action_audit_events','superadmin_role_approval_records','superadmin_role_assignments','support_events','support_mode_action_events','support_mode_sessions','token_scan_batch_runs','token_scan_events','token_scan_runs','transactional_email_events','ucl_events','ucl_repair_actions','ucl_validation_runs','ucl_xflow_connections','ucl_xflow_links','usage_events','user_ai_memory','user_backup_codes','user_email_verification_tokens','user_entitlement_grants','user_legal_consents','user_org_roles','user_password_reset_tokens','validations','webauthn_challenges','webhook_delivery_logs','webhook_endpoints','webhook_event_subscriptions','webhook_inbound_events','webhook_outbound_deliveries','workspace_ai_memory','workspace_app_connections','workspace_app_tokens','workspace_billing_accounts','workspace_connection_activity','workspace_connections',