rrides','guard_rules','guard_runtime_evaluations','guard_validation_findings','guard_validation_runs','idempotency_cache','inbound_replay_guards','ingest_rate_buckets','integration_runtime_state','job_runs','jobs','meter_app_xflow_links','meter_apps','meter_ingest_rejections','meter_model_rates','meter_usage_events','metric_definitions','metric_snapshots','mfa_reset_tokens','operator_readiness_impact_events','orgs','ownership_verifications','payment_monitor_stripe_mappings','project_github_connections','project_scan_files','project_scan_findings','project_scan_reports','project_scan_runs','project_scan_source_payloads','redaction_audit_events','requests_log','responsive_audit_runs','responsive_ignore_rules','sanctions_screening_runs','scan_schedules','scans','security_alert_events','security_audit_exports','security_audit_logs','security_findings','security_integrations','security_notification_preferences','security_scan_artifacts','security_scan_checks','security_scan_schedules','security_scans','sessions','site_audit_schedules','stripe_events','stripe_webhook_processing','stripe_webhook_rate_buckets','subscription_items','superadmin_action_audit_events','superadmin_role_approval_records','superadmin_role_assignments','support_events','support_mode_action_events','support_mode_sessions','token_scan_batch_runs','token_scan_events','token_scan_runs','transactional_email_events','ucl_events','ucl_repair_actions','ucl_validation_runs','ucl_xflow_connections','ucl_xflow_links','usage_events','user_ai_memory','user_backup_codes','user_email_verification_tokens','user_entitlement_grants','user_legal_consents','user_org_roles','user_password_reset_tokens','validations','webauthn_challenges','webhook_delivery_logs','webhook_endpoints','webhook_event_subscriptions','webhook_inbound_events','webhook_outbound_deliveries','workspace_ai_memory','workspace_app_connections','workspace_app_tokens','workspace_billing_accounts','workspace_connection_activity','workspace_connections',